//! The ISP pipeline's interrupt sources, every one named, generated by tools/gen-isp-events.py from the Pixel kernel's LWIS event tables.
//!
//! Do not edit by hand. `zuma-isp-event-info.dtsi` plus `dt-bindings/lwis/platform/zuma/*.h` name every event register and every bit in it; LWIS is only a passthrough, but its device tree is where the ISP front end's register semantics are written down in the open.
//! Reading these and printing the set bits by name is what turns register archaeology into a reading of the pipeline: which stage is alive, and where it goes quiet.

/// A block's register base, as `lwis_isp_fe`'s `reg`/`reg-names` pair them.
pub const SPACES: [(&str, usize); 5] = [
    ("isp-fe", 0x1C300000),
    ("csis-link-phy", 0x1C040000),
    ("isp-fe-sysreg", 0x1C020000),
    ("pdma", 0x1C390000),
    ("pdma-wrap", 0x1C395000),
];

/// One interrupt source: its space base, offset, mask-register offset (0 when it has none), node name, kind, and the name of each bit.
pub struct Source {
    pub base: usize,
    pub off: usize,
    pub mask_off: usize,
    pub name: &'static str,
    pub kind: &'static str,
    pub bits: &'static [(u8, &'static str)],
}

